 rows[,state:=c(if(all(de$FDR<.05))'Association'else'Limited',if(nrow(rv))'Covered'else'Not evaluable',if(meta$status!='completed')'Not evaluable'else if(nlocal)'Limited'else'Not significant',if(!nrow(ga))'Not evaluable'else if(any(ga$padj<.05))'Association'else'Not significant',if(!nrow(tf))'Not evaluable'else if(any(c(tf$sample_model_q,sca$sample_model_q)<.05))'Association'else'Not significant',if(tt$status!='completed')'Not evaluable'else if(tt$n_targets<10)'Limited'else'Association','Pending')]
 rows[,detail:=c(paste0(de$target,': ',sprintf('%+.2f',de$logFC),collapse='\n'),paste0(rv$gene,': ',sprintf('%.2f',100*rv$median_detection),'%',collapse='\n'),if(meta$status=='completed')paste0(nlocal,' local / ',njoint,' joint')else'NE',if(nrow(ga))paste0(sum(ga$padj<.05),' sets q < 0.05')else'NE',if(nrow(tf))paste0('CT ',sum(tf$sample_model_q<.05),' / SC ',if(nrow(sca))sum(sca$sample_model_q<.05)else'NE')else'NE',if(is.na(tt$n_targets))'NE'else paste0(tt$n_targets,' targets'),'Pending')];out[[paste(lig,r)]]<-rows
};put(rbindlist(out),'axis_evidence_comparison.tsv');cat('AXIS COMPARISON COMPLETE\n')
